{"command":"set -o pipefail
REPO='edburns/dd-3070094-cargotracker-darwin-arm64-01'; TASK_ISSUE=4
{
  gh api "/repos/$REPO/issues/$TASK_ISSUE/timeline?per_page=100" --paginate --jq '.[] | select(.event == "cross-referenced") | select(.source.issue.pull_request != null) | .source.issue.pull_request.url'
  gh pr list -R "$REPO" --state open --json number,body,title,headRefName --jq ".[] | select(((.body // \"\") | test(\"(^|[^0-9])#$TASK_ISSUE([^0-9]|$)\")) or ((.title // \"\") | test(\"(^|[^0-9])$TASK_ISSUE([^0-9]|$)\"; \"i\")) or ((.headRefName // \"\") | test(\"(^|[^0-9])$TASK_ISSUE([^0-9]|$)\"))) | .number"
} | awk '!seen[$0]++'","description":"Discover linked PR candidates","initial_wait":600,"mode":"sync"}
